// OpenTelemetry Node SDK for Next.js: traces + metrics over OTLP/HTTP. Generated by `eos scaffold otel-node`.
// {{PM}} add @opentelemetry/api @opentelemetry/sdk-node @opentelemetry/exporter-trace-otlp-http \
//   @opentelemetry/exporter-metrics-otlp-http @opentelemetry/sdk-metrics
// Configure with the standard env vars (same as the Python services):
//   OTEL_SERVICE_NAME=web  OTEL_EXPORTER_OTLP_ENDPOINT=http://collector:4318
//   OTEL_TRACES_SAMPLER=parentbased_traceidratio  OTEL_TRACES_SAMPLER_ARG=0.1  OTEL_SDK_DISABLED=true
// No endpoint set: nothing starts (logs from lib/logger still work). Why: .eos/packs/ref/ops/opentelemetry.md
import { OTLPMetricExporter } from "@opentelemetry/exporter-metrics-otlp-http";
import { OTLPTraceExporter } from "@opentelemetry/exporter-trace-otlp-http";
import { PeriodicExportingMetricReader } from "@opentelemetry/sdk-metrics";
import { NodeSDK } from "@opentelemetry/sdk-node";

const env = process.env;
const enabled =
  env.OTEL_SDK_DISABLED?.toLowerCase() !== "true" &&
  Boolean(env.OTEL_EXPORTER_OTLP_ENDPOINT || env.OTEL_EXPORTER_OTLP_TRACES_ENDPOINT);

if (enabled) {
  const sdk = new NodeSDK({
    serviceName: env.OTEL_SERVICE_NAME ?? "{{PROJECT_NAME}}",
    traceExporter: new OTLPTraceExporter(), // batched; endpoint and headers from OTEL_EXPORTER_OTLP_*
    metricReaders: [new PeriodicExportingMetricReader({ exporter: new OTLPMetricExporter() })],
  });
  sdk.start();
  // Flush what is buffered when the platform stops the container.
  process.once("SIGTERM", () => {
    sdk.shutdown().catch(() => undefined);
  });
}
